"use client";

import type * as React from "react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarRail,
} from "@/core/sidebar/sidebar";
import { NavSection } from "./nav-section";
import { NavUser } from "./nav-user";
import { TeamSwitcher } from "./team-switcher";
import type { AppSidebarData, AppSidebarTeam, AppSidebarUserAction } from "./types";

type AppSidebarProps = React.ComponentProps<typeof Sidebar> & {
  data: AppSidebarData;
  onTeamChange?: (team: AppSidebarTeam) => void;
  /** Shows an "Add team" entry in the team switcher. */
  onAddTeam?: () => void;
  onUserAction?: (action: AppSidebarUserAction) => void;
};

/**
 * App-shell sidebar (shadcn "sidebar-07"): collapsible to icons, with a team
 * switcher or logo, one section per `data.nav` entry and a user menu.
 * Render it inside a `SidebarProvider`.
 */
export function AppSidebar({
  data,
  onTeamChange,
  onAddTeam,
  onUserAction,
  ...props
}: AppSidebarProps) {
  return (
    <Sidebar collapsible="icon" {...props}>
      <SidebarHeader>
        <TeamSwitcher
          teams={data.teams}
          logo={data.logo}
          onTeamChange={onTeamChange}
          onAddTeam={onAddTeam}
        />
      </SidebarHeader>
      <SidebarContent>
        {data.nav.map((section) => (
          <NavSection key={section.title} section={section} />
        ))}
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={data.user} onAction={onUserAction} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

export type * from "./types";
export type { AppSidebarProps };

"use client";

import { ChevronRightIcon, MoreHorizontalIcon } from "lucide-react";
import { Collapsible, CollapsibleContent } from "@/core/collapsible/collapsible";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { AppSidebarNavItem, AppSidebarNavSection } from "./types";

export function NavSection({ section }: { section: AppSidebarNavSection }) {
  const { isMobile, state } = useSidebar();
  const isIconCollapsed = state === "collapsed" && !isMobile;

  return (
    <SidebarGroup>
      <SidebarGroupLabel>{section.title}</SidebarGroupLabel>
      <SidebarMenu>
        {section.items.map((item) => {
          if (!item.items?.length) {
            return (
              <SidebarMenuItem key={item.title}>
                <SidebarMenuButton
                  href={item.url}
                  isActive={item.isActive}
                  aria-current={item.isActive ? "page" : undefined}
                  tooltip={item.title}
                >
                  {item.icon}
                  <span>{item.title}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            );
          }
          // Icon-only sidebars have no room for inline sub-items.
          const variant = isIconCollapsed ? "dropdown" : (item.variant ?? "collapse");
          return variant === "dropdown" ? (
            <DropdownItem key={item.title} item={item} withLabel={isIconCollapsed} />
          ) : (
            <CollapseItem key={item.title} item={item} />
          );
        })}
      </SidebarMenu>
    </SidebarGroup>
  );
}

function CollapseItem({ item }: { item: AppSidebarNavItem }) {
  return (
    <SidebarMenuItem>
      <Collapsible defaultExpanded={item.isActive} className="group/collapsible">
        <SidebarMenuButton slot="trigger" tooltip={item.title}>
          {item.icon}
          <span>{item.title}</span>
          <ChevronRightIcon
            aria-hidden="true"
            className="ml-auto transition-transform duration-200 group-data-expanded/collapsible:rotate-90"
          />
        </SidebarMenuButton>
        <CollapsibleContent>
          <SidebarMenuSub>
            {item.items?.map((subItem) => (
              <SidebarMenuSubItem key={subItem.title}>
                <SidebarMenuSubButton href={subItem.url} className="w-full">
                  {subItem.icon}
                  <span>{subItem.title}</span>
                </SidebarMenuSubButton>
              </SidebarMenuSubItem>
            ))}
          </SidebarMenuSub>
        </CollapsibleContent>
      </Collapsible>
    </SidebarMenuItem>
  );
}

function DropdownItem({ item, withLabel }: { item: AppSidebarNavItem; withLabel: boolean }) {
  const { isMobile } = useSidebar();
  return (
    <SidebarMenuItem>
      <DropdownMenuTrigger>
        <SidebarMenuButton
          tooltip={item.title}
          className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
        >
          {item.icon}
          <span>{item.title}</span>
          <MoreHorizontalIcon aria-hidden="true" className="ml-auto" />
        </SidebarMenuButton>
        <DropdownMenu
          aria-label={item.title}
          placement={isMobile ? "bottom start" : "end top"}
          className="w-fit min-w-40"
        >
          {withLabel && (
            <>
              <DropdownMenuLabel>{item.title}</DropdownMenuLabel>
              <DropdownMenuSeparator />
            </>
          )}
          {item.items?.map((subItem) => (
            <DropdownMenuItem key={subItem.title} id={subItem.title} href={subItem.url}>
              {subItem.icon}
              <span>{subItem.title}</span>
            </DropdownMenuItem>
          ))}
        </DropdownMenu>
      </DropdownMenuTrigger>
    </SidebarMenuItem>
  );
}

"use client";

import {
  BadgeCheckIcon,
  BellIcon,
  ChevronsUpDownIcon,
  CreditCardIcon,
  LogOutIcon,
  SparklesIcon,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/core/avatar/avatar";
import {
  DropdownMenu,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { AppSidebarUser, AppSidebarUserAction } from "./types";

function initials(name: string) {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

function UserSummary({ user }: { user: AppSidebarUser }) {
  return (
    <>
      <Avatar>
        <AvatarImage src={user.avatar} alt="" />
        <AvatarFallback>{initials(user.name)}</AvatarFallback>
      </Avatar>
      <div className="grid flex-1 text-left text-sm leading-tight">
        <span className="truncate font-medium">{user.name}</span>
        <span className="truncate text-xs">{user.email}</span>
      </div>
    </>
  );
}

export function NavUser({
  user,
  onAction,
}: {
  user: AppSidebarUser;
  onAction?: (action: AppSidebarUserAction) => void;
}) {
  const { isMobile } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`Account: ${user.name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            <UserSummary user={user} />
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto size-4" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom end" : "end bottom"}
            className="w-fit min-w-56"
            onAction={(key) => onAction?.(key as AppSidebarUserAction)}
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel className="flex items-center gap-2 px-1 py-1.5 font-normal text-foreground">
                <UserSummary user={user} />
              </DropdownMenuLabel>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuItem id="upgrade" textValue="Upgrade to Pro">
              <SparklesIcon aria-hidden="true" />
              Upgrade to Pro
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuItem id="account" textValue="Account">
                <BadgeCheckIcon aria-hidden="true" />
                Account
              </DropdownMenuItem>
              <DropdownMenuItem id="billing" textValue="Billing">
                <CreditCardIcon aria-hidden="true" />
                Billing
              </DropdownMenuItem>
              <DropdownMenuItem id="notifications" textValue="Notifications">
                <BellIcon aria-hidden="true" />
                Notifications
              </DropdownMenuItem>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuItem id="logout" textValue="Log out">
              <LogOutIcon aria-hidden="true" />
              Log out
            </DropdownMenuItem>
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";

import { ChevronsUpDownIcon, PlusIcon } from "lucide-react";
import * as React from "react";
import {
  DropdownMenu,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import type { AppSidebarLogo, AppSidebarTeam } from "./types";

export function TeamSwitcher({
  teams,
  logo,
  onTeamChange,
  onAddTeam,
}: {
  teams?: AppSidebarTeam[];
  logo?: AppSidebarLogo;
  onTeamChange?: (team: AppSidebarTeam) => void;
  onAddTeam?: () => void;
}) {
  const { isMobile } = useSidebar();
  const [activeTeam, setActiveTeam] = React.useState(teams?.[0]);

  if (!teams?.length || !activeTeam) {
    // Same footprint as the switcher button, so collapsing behaves alike.
    return (
      <SidebarMenu>
        <SidebarMenuItem>
          <div
            data-slot="app-sidebar-logo"
            className="flex h-12 w-full items-center justify-center overflow-hidden rounded-md group-data-[collapsible=icon]:size-8!"
          >
            <div className="flex size-full items-center justify-center group-data-[collapsible=icon]:hidden">
              {logo?.full}
            </div>
            <div className="hidden size-full items-center justify-center group-data-[collapsible=icon]:flex">
              {logo?.collapsed}
            </div>
          </div>
        </SidebarMenuItem>
      </SidebarMenu>
    );
  }

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`Team: ${activeTeam.name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              {activeTeam.logo}
            </div>
            <div className="grid flex-1 text-left text-sm leading-tight">
              <span className="truncate font-medium">{activeTeam.name}</span>
              <span className="truncate text-xs">{activeTeam.plan}</span>
            </div>
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom start" : "end top"}
            className="w-fit min-w-56"
            onAction={(key) => {
              if (key === "add-team") return onAddTeam?.();
              const team = teams.find((candidate) => candidate.name === key);
              if (!team) return;
              setActiveTeam(team);
              onTeamChange?.(team);
            }}
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel>Teams</DropdownMenuLabel>
              {teams.map((team, index) => (
                <DropdownMenuItem key={team.name} id={team.name} className="gap-2 p-2">
                  <div className="flex size-6 items-center justify-center rounded-md border">
                    {team.logo}
                  </div>
                  {team.name}
                  <DropdownMenuShortcut>⌘{index + 1}</DropdownMenuShortcut>
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
            {onAddTeam && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem id="add-team" textValue="Add team" className="gap-2 p-2">
                  <div className="flex size-6 items-center justify-center rounded-md border">
                    <PlusIcon aria-hidden="true" className="size-4" />
                  </div>
                  <span className="font-medium text-muted-foreground">Add team</span>
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

import type * as React from "react";

/**
 * Data contract for the `app-sidebar` block: adding or removing a team,
 * section, item or sub-item is a change to this data, not to the block.
 */

export type AppSidebarUser = {
  name: string;
  email: string;
  avatar: string;
};

export type AppSidebarTeam = {
  name: string;
  logo: React.ReactNode;
  plan: string;
};

/**
 * `full` shows while the sidebar is expanded (and on mobile); `collapsed`
 * while it's retracted to icons. Swapped with CSS only.
 */
export type AppSidebarLogo = {
  full: React.ReactNode;
  collapsed: React.ReactNode;
};

/** Either a team switcher or a static logo fills the header. */
export type AppSidebarBranding =
  | { teams: AppSidebarTeam[]; logo?: never }
  | { teams?: never; logo: AppSidebarLogo };

/**
 * Links are react-aria `Link`s: wrap the app in react-aria's `RouterProvider`
 * to route them client-side.
 */
export type AppSidebarNavSubItem = {
  title: string;
  url: string;
  icon?: React.ReactNode;
};

/**
 * `variant` picks how an item with sub-items opens: `"collapse"` (default)
 * expands them inline, `"dropdown"` opens a menu beside the item. While the
 * sidebar is collapsed to icons every item uses the dropdown.
 */
export type AppSidebarNavItem = {
  title: string;
  url: string;
  icon?: React.ReactNode;
  /** Marks the current page and starts a collapse item expanded. */
  isActive?: boolean;
  variant?: "collapse" | "dropdown";
  items?: AppSidebarNavSubItem[];
};

/** A sidebar section, rendered as a `SidebarGroup`. */
export type AppSidebarNavSection = {
  title: string;
  items: AppSidebarNavItem[];
};

export type AppSidebarData = {
  user: AppSidebarUser;
  nav: AppSidebarNavSection[];
} & AppSidebarBranding;

/** Ids of the entries in the user menu, passed to `onUserAction`. */
export type AppSidebarUserAction = "upgrade" | "account" | "billing" | "notifications" | "logout";
